def interleave(left, right, reverse_pairs=False, keep_remainder=False):
    output = []
    for a, b in zip(left, right):
        output.extend((b, a) if reverse_pairs else (a, b))
    if keep_remainder:
        remaining = len(left) - len(output) // 2
        output.extend(left[remaining:])
        output.extend(right[remaining:])
    return output

