    if strict and any(start > end for start, end in intervals):
        raise ValueError('invalid interval')
    output = []
    for start, end in sorted(intervals):
        overlaps = output and (start <= output[-1][1] if merge_touching else start < output[-1][1])
        if overlaps:
            output[-1] = (output[-1][0], max(output[-1][1], end))
        else:
            output.append((start, end))
    return output

